"""Tribal Battle Awakening, both takes, generated by phrase_level (loudest half-beat slots, one motif per section).

Song data (tempo, offset, sections, cameras) comes from the hand charts next to this file; the tool only picks
the taps. Writes tribal_battle_awakening_tool / tribal_battle_awakening_take2_tool chart files.
Usage: python tools/charting/levels/tribal_battle_awakening_tool.py   Related: tools/charting/phrase_level.py
"""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from phrase_level import build_phrase_level  # noqa: E402
from tribal_battle_awakening import SONG as TAKE1  # noqa: E402
from tribal_battle_awakening_take2 import SONG as TAKE2  # noqa: E402

