    {"start": 192, "end": 240, "taps": 6, "gap": 1.0, "keep_db": 8.0, "patterns": ["spike", "dl", "step", "dr", "gap"]},
    {"start": 240, "end": 288, "taps": 5, "gap": 1.5, "patterns": ["spike", "step", "gap", "flip"]},
