    {"start": 64, "end": 128, "taps": 3, "gap": 2.0, "patterns": ["spike", "step", "gap", "dl"]},
    {"start": 128, "end": 184, "taps": 7, "gap": 1.0, "keep_db": 8.0, "patterns": ["spike", "step", "gap", "flip"]},
