def tool_song(song, title):
    audio = song["audio"]
    return dict(song, id=audio + "_tool", title=title, path="assets/music/%s.mp3" % audio)


if __name__ == "__main__":
    build_phrase_level(tool_song(TAKE1, "Tribal Battle Awakening (Tool)"), TAKE1_RULES)
    build_phrase_level(tool_song(TAKE2, "Tribal Battle Awakening 2 (Tool)"), TAKE2_RULES)
